#include <iostream>
#include <vector>
#define rep(i, n) for (int i = 0; i < (n); i++)
using namespace std;

int main() {
	int h, w;
	cin >> h >> w;
	vector<vector<char>> c(h, vector<char>(w));
	rep(i, h) rep(j, w) cin >> c[i][j];
	vector<vector<int>> x(h, vector<int>(26));
	vector<vector<int>> y(w, vector<int>(26));
	rep(i, h) rep(j, w) {
		x[i][c[i][j] - 'a']++;
		y[j][c[i][j] - 'a']++;
	}
	int hc = h, wc = w;
	vector<bool> fx(h), fy(w);
	rep(_, h + w) {
		vector<pair<int, int>> ux, uy;
		rep(i, h) {
			if (fx[i]) continue;
			rep(j, 26) {
				if (x[i][j] == wc && wc >= 2) {
					ux.push_back({ i, j });
				}
			}
		}
		rep(i, w) {
			if (fy[i]) continue;
			rep(j, 26) {
				if (y[i][j] == hc && hc >= 2) {
					uy.push_back({ i, j });
				}
			}
		}
		for (pair<int, int> p : ux) {
			fx[p.first] = true;
			rep(i, w) y[i][p.second]--;
			hc--;
		}
		for (pair<int, int> p : uy) {
			fy[p.first] = true;
			rep(i, h) x[i][p.second]--;
			wc--;
		}
	}
	cout << hc * wc << '\n';
}

#include <iostream>
#include <vector>
using namespace std;
#define ll long long
ll square(ll x){
    return x*x;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    //以上為輸入輸出流速度優化
    int H, W;
    cin >> H >> W;
    vector<pair<ll, ll>> row_sum(H, {0, 0});
    vector<pair<ll, ll>> column_sum(W, {0, 0});
    for(int i=0;i<H;i++){
        string s;
        cin >> s;
        for(int j=0;j<W;j++){
            int ind=s[j]-'a';
            row_sum[i].first+=ind;
            row_sum[i].second+=ind*ind;
            column_sum[j].first+=ind;
            column_sum[j].second+=ind*ind;
        }
    }
    pair<ll, ll> row_sum_delta={0, 0};
    pair<ll, ll> column_sum_delta={0, 0};
    while(true){
        vector<int> index_rowToDelete;
        vector<int> index_columnToDelete;
        ll column_sum_delta1=0;
        ll column_sum_delta2=0;
        if(W>1){
            for(int i=0;i<H;i++){
                if((row_sum[i].second-row_sum_delta.second)*W==square(row_sum[i].first-row_sum_delta.first)){
                    index_rowToDelete.push_back(i);
                    int ind=(row_sum[i].first-row_sum_delta.first)/W;
                    column_sum_delta1+=ind;
                    column_sum_delta2+=square(ind);
                }
            }
        }
        if(H>1){
            for(int i=0;i<W;i++){
                if((column_sum[i].second-column_sum_delta.second)*H==square(column_sum[i].first-column_sum_delta.first)){
                    index_columnToDelete.push_back(i);
                    int ind=(column_sum[i].first-column_sum_delta.first)/H;
                    row_sum_delta.first+=ind;
                    row_sum_delta.second+=square(ind);
                }
            }
        }
        if(index_rowToDelete.empty() && index_columnToDelete.empty()){
            cout << H*W;
            return 0;
        }
        //改H, W, row_sum, column_sum
        column_sum_delta.first+=column_sum_delta1;
        column_sum_delta.second+=column_sum_delta2;
        vector<pair<ll, ll>> new_row_sum;
        vector<pair<ll, ll>> new_column_sum;
        for(int i=0, ind=0;i<H; i++){
            if(ind<index_rowToDelete.size() && i==index_rowToDelete[ind]){
                ind++;
            }
            else{
                new_row_sum.push_back(row_sum[i]);
            }
        }
        for(int j=0, ind=0;j<W;j++){
            if(ind<index_columnToDelete.size() && j==index_columnToDelete[ind]){
                ind++;
            }
            else{
                new_column_sum.push_back(column_sum[j]);
            }
        }
        row_sum=new_row_sum;
        column_sum=new_column_sum;
        H=row_sum.size();
        W=column_sum.size();
    }
    return 0;
}

H, W = map(int, input().split())
c = [list(input()) for _ in range(H)]
A = 26

row = [[0] * A for _ in range(H)]
row_c = [0] * H
col = [[0] * A for _ in range(W)]
col_c = [0] * W
num_row, num_col = H, W

for i in range(H):
    for j in range(W):
        v = ord(c[i][j]) - ord('a')
        row[i][v] += 1
        if row[i][v] == 1:
            row_c[i] += 1
        col[j][v] += 1
        if col[j][v] == 1:
            col_c[j] += 1

while True:
    del_row, del_col = [], []
    for i in range(H):
        if row_c[i] == 1 and num_col >= 2:
            del_row.append(i)
    for j in range(W):
        if col_c[j] == 1 and num_row >= 2:
            del_col.append(j)
    if del_row == [] and del_col == []:
        break

    def remove(i, j):
        if c[i][j] != ' ':
            v = ord(c[i][j]) - ord('a')
            row[i][v] -= 1
            if row[i][v] == 0:
                row_c[i] -= 1
            col[j][v] -= 1
            if col[j][v] == 0:
                col_c[j] -= 1
            c[i][j] = ' '

    for i in del_row:
        for j in range(W):
            remove(i, j)
        num_row -= 1
    for j in del_col:
        for i in range(H):
            remove(i, j)
        num_col -= 1

print(num_row * num_col)
